const fs = await import('node:fs/promises');
const path = await import('node:path');
const { execFileSync } = await import('node:child_process');
const cwd = nodeRepl.cwd;
const files = execFileSync('rg', ['--files','-g','*.md'], {cwd, encoding:'utf8'}).trim().split(/\n/).filter(Boolean);
const stems = new Set(files.map(f => path.basename(f, '.md')));
const badLinks=[];
const tableIssues=[];
const multiH1=[];
for (const f of files) {
  const text = await fs.readFile(path.join(cwd,f),'utf8');
  const lines = text.split(/\n/);
  const h1 = lines.filter(l => /^# /.test(l)).length;
  if (h1 > 1) multiH1.push([f,h1]);
  for (let i=0;i<lines.length;i++) {
    const re=/\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|[^\]]*)?\]\]/g; let m;
    while ((m=re.exec(lines[i]))) {
      if (!stems.has(m[1])) badLinks.push(`${f}:${i+1}: [[${m[1]}]]`);
    }
    if (/^\|/.test(lines[i]) && i>0 && lines[i-1].trim() !== '' && !/^\|/.test(lines[i-1])) tableIssues.push(`${f}:${i+1}`);
  }
}
nodeRepl.write(JSON.stringify({files: files.length, badLinks, tableIssues, multiH1}, null, 2));
